"""Generate substantive, bilingual problem pages. No hosting or publishing."""
from pathlib import Path
from html import escape
import json

root=Path(__file__).resolve().parent
cosmic_mark=(root/"assets/cosmic-mark.svg").read_text().strip().replace("<svg ","<svg class=\"cosmic-mark\" aria-hidden=\"true\" focusable=\"false\" ",1)
pages=[
dict(nl='medewerkers-meekrijgen-in-verandering',en='engaging-employees-in-change',
title=['Hoe krijg je medewerkers mee in verandering?','How do you engage employees in change?'],
intro=['Begin met begrijpen wat er voor mensen verandert. Bezwaren kunnen informatie bevatten over werkdruk, invloed, onduidelijke doelen of praktische knelpunten. Een ervaring kan helpen die verschillen zichtbaar te maken en samen alternatieven te onderzoeken.','Start by understanding what is changing for people. Concerns can reveal workload issues, a lack of influence, unclear goals or practical obstacles. A shared experience can make those differences visible and help people explore alternatives.'],
heading=['Iedereen hoort hetzelfde plan. Niet iedereen beleeft hetzelfde probleem.','Everyone hears the same plan. Not everyone experiences the same problem.'],
body=['Een nieuw proces kan voor de ene afdeling overzicht betekenen en voor de andere extra werk. Nog een presentatie maakt dat verschil niet vanzelf bespreekbaar. Vraag eerst welke gevolgen mensen verwachten, welke zorgen al zijn onderzocht en waar nog invloed mogelijk is. Niet ieder probleem vraagt om een game: soms ontbreekt een besluit, capaciteit of een heldere afspraak.','A new process may create clarity for one department and extra work for another. Another presentation will not automatically open up that difference. First ask what consequences people expect, which concerns have been explored and where people can still influence the change. A game is not always the answer: sometimes a decision, capacity or a clear agreement is missing.'],
steps=[['Maak het concreet: welk gedrag of welke samenwerking moet anders, en waarom?','Onderzoek perspectieven: laat mensen hun afhankelijkheden en afwegingen delen.','Oefen met een herkenbare situatie waarin keuzes gevolgen hebben.','Bespreek wat er gebeurde en kies één afspraak om in het echte werk te testen.'],['Be specific: what behaviour or collaboration needs to change, and why?','Explore perspectives: let people share their dependencies and trade-offs.','Practise in a recognisable situation where decisions have consequences.','Reflect on what happened and choose one agreement to test at work.']],
case=['Plan je Rot — Rijkswaterstaat / E2i','Plan je Rot — Rijkswaterstaat / E2i'],
casebody=['Voor Rijkswaterstaat ontwierp en faciliteerde ik een game over statisch plannen en meeroosteren. Medewerkers namen verschillende rollen aan en ervoeren de gevolgen en belangen achter planningskeuzes. Dat is een voorbeeld van mijn aanpak: het vraagstuk wordt iets wat je samen kunt onderzoeken.','For Rijkswaterstaat, I designed and facilitated a game about fixed and collaborative scheduling. Employees took on different roles to experience the consequences and competing interests behind planning decisions. This illustrates my approach: making a challenge something people can explore together.'],
fit=['Voor veranderverantwoordelijken, projectleiders en HR-professionals die verschillende perspectieven willen onderzoeken. We beginnen met het vraagstuk, de doelgroep en de ruimte om na de sessie iets anders te doen. Een sessie vervangt geen volledig verandertraject.','For change leads, project managers and HR professionals who want to explore different perspectives. We begin with the challenge, the participants and the room to act differently afterwards. A session does not replace a complete change programme.'],
prompt=['Welke verandering proberen jullie door te voeren, en waar loopt het vast?','What change are you trying to make, and where is it getting stuck?']),
dict(nl='samenwerking-tussen-afdelingen',en='collaboration-between-teams',
title=['Hoe verbeter je de samenwerking tussen afdelingen?','How do you improve collaboration between teams?'],
intro=['Maak zichtbaar waar teams elkaar nodig hebben. Onderzoek vervolgens wat er bij overdrachten, beslissingen en informatie delen misgaat. Een gedeelde simulatie kan helpen om het werk vanuit een ander perspectief te bekijken.','Make it visible where teams depend on each other. Then examine what happens at handovers, decisions and information sharing. A shared simulation can help people see the work from another perspective.'],
heading=['Van “zij leveren te laat” naar “wat hebben we van elkaar nodig?”','From “they’re always late” to “what do we need from each other?”'],
body=['Samenwerking is meer dan elkaar aardig vinden. Verschillende doelen, begrippen en werkwijzen kunnen spanning veroorzaken, ook als iedereen zijn eigen werk goed probeert te doen. Begin daarom met één concrete situatie: waar bleef informatie hangen, ontstond dubbel werk of werd een beslissing vooruitgeschoven? Bespreek wat iedere partij wist en nodig had.','Collaboration involves more than getting along. Different goals, language and ways of working can create friction even when everyone is trying to do their own job well. Start with a specific situation: where did information get stuck, work get duplicated or a decision get delayed? Explore what each person knew and needed.'],
steps=[['Breng één gezamenlijke werkstroom in kaart, inclusief de overdrachten.','Laat mensen hun eigen keuzes uitleggen voordat je oplossingen bedenkt.','Oefen met rolwisseling of een simulatie waarin afhankelijkheden tastbaar worden.','Kies een concrete werkafspraak en plan wanneer je samen terugkijkt.'],['Map one shared workflow, including its handovers.','Let people explain their decisions before proposing solutions.','Use perspective-taking or a simulation to make dependencies tangible.','Choose a concrete working agreement and schedule a shared review.']],
case=['Order-to-Pay LEGO-game — Croonwolter&dros / Proexc','Order-to-Pay LEGO game — Croonwolter&dros / Proexc'],
casebody=['Ik ontwierp en faciliteerde een LEGO-simulatie als start van procesverbetering. Medewerkers onderzochten samen knelpunten in het inkoopproces. In een fysieke opdracht worden informatie, timing en afhankelijkheden iets wat je kunt zien en bespreken.','I designed and facilitated a LEGO simulation to begin a process improvement project. Employees explored bottlenecks in procurement together. A physical challenge makes information, timing and interdependencies visible and open for discussion.'],
fit=['Voor teamleiders, procesverantwoordelijken en HR/L&D die samenwerking over teamgrenzen willen onderzoeken. Als werkafspraken, middelen of bevoegdheden ontbreken, nemen we dat mee in de analyse. Alleen een leuke middag verandert de structuur niet.','For team leaders, process owners and HR/L&D professionals exploring collaboration across team boundaries. Missing agreements, resources or decision-making authority belong in the diagnosis. An enjoyable afternoon alone will not change the structure.'],
prompt=['Waar hebben jullie afdelingen elkaar nodig, maar loopt de samenwerking vast?','Where do your teams depend on each other, but struggle to work together?']),
dict(nl='leren-door-ervaring',en='experiential-learning',
title=['Hoe maak je leren actief en toepasbaar?','How do you make learning active and practical?'],
intro=['Begin bij wat deelnemers in de praktijk moeten kunnen. Geef ze vervolgens een situatie om te oefenen, ruimte om terug te kijken en een concrete stap voor hun eigen werk. De vorm volgt de leervraag.','Start with what participants need to do in practice. Give them a situation to try, space to reflect and a concrete next step for their own work. The format follows the learning need.'],
heading=['Een inzicht begrijpen is iets anders dan ermee werken.','Understanding an insight is different from putting it into practice.'],
body=['Een inspirerende sessie kan nieuwsgierigheid oproepen. Om verder te komen, moet er ook iets te onderzoeken of te proberen zijn. Welke keuze durft iemand nog niet te maken? Welk gesprek wordt uitgesteld? Welke samenwerking vraagt oefening? Door een leerdoel te koppelen aan een herkenbare situatie wordt duidelijk waarom een ervaring relevant is.','An inspiring session can spark curiosity. To take it further, people also need something to investigate or try. Which decision feels difficult? Which conversation keeps getting postponed? What collaboration needs practice? Linking a learning goal to a recognisable situation makes the relevance of an experience clear.'],
steps=[['Formuleer een leerdoel als een handeling, niet alleen als een onderwerp.','Ontwerp een veilige oefensituatie met keuzes, feedback en ruimte om te experimenteren.','Neem tijd voor reflectie: wat gebeurde er en welke aannames speelden mee?','Laat deelnemers een klein experiment kiezen en organiseer een terugkoppelmoment.'],['Frame the learning goal as an action, rather than just a topic.','Design a safe practice situation with choices, feedback and room to experiment.','Make time to reflect: what happened and which assumptions shaped it?','Let participants choose a small experiment and arrange a follow-up.']],
case=['Positive Health Experience & The Nightingale Society','Positive Health Experience & The Nightingale Society'],
casebody=['Voor zorgprofessionals ontwierp ik drie interactieve ruimtes rond de zes dimensies van Positieve Gezondheid. In The Nightingale Society werkten zorgtrainees in een weeklange blended game aan innovatievraagstukken en een prototype. Twee vormen, met een verschillende leervraag als vertrekpunt.','I designed three interactive rooms for healthcare professionals to explore the six dimensions of Positive Health. In The Nightingale Society, healthcare trainees worked on innovation challenges and a prototype during a week-long blended game. Two different formats, each starting with its own learning challenge.'],
fit=['Voor L&D-professionals, opleidingscoördinatoren en programmamakers, onder meer in zorg en publieke organisaties. We kiezen samen tussen een workshop, serious game of immersieve ervaring, passend bij deelnemers en context. Toepassing na afloop vraagt ook aandacht in de werkomgeving.','For L&D professionals, learning coordinators and programme designers, including healthcare and public-sector organisations. Together, we choose a workshop, serious game or immersive experience to fit the participants and context. Applying learning afterwards also requires attention in the workplace.'],
prompt=['Wat moeten deelnemers na het leren anders kunnen doen?','What should participants be able to do differently after learning?']),
dict(nl='patronen-doorbreken',en='breaking-patterns',
title=['Hoe help je mensen vaste patronen te doorbreken?','How do you help people break familiar patterns?'],
intro=['Maak een patroon eerst herkenbaar. Onderzoek wat het oplevert en wat het in de weg zit. Kies daarna een klein experiment dat ruimte geeft voor een ander perspectief, zonder de uitkomst vooraf dicht te timmeren.','First make a pattern recognisable. Explore what it offers and what it gets in the way of. Then choose a small experiment that opens up a different perspective without deciding the outcome in advance.'],
heading=['Persoonlijke ontwikkeling begint niet altijd met meer uitleg.','Personal development does not always begin with more explanation.'],
body=['Soms begrijp je prima wat je doet, maar helpt een andere omgeving of opdracht om iets nieuws op te merken. Storytelling, spel en reflectie kunnen daarvoor een ingang zijn. Daarbij hoeft niet iedereen hetzelfde te ervaren. Deelnemers hebben ruimte nodig voor eigen keuzes en voor wat zij wel of niet willen delen.','Sometimes you understand your behaviour, but a different environment or activity helps you notice something new. Storytelling, play and reflection can offer a way in. Participants do not all need to have the same experience. They need room for their own choices and for deciding what they want to share.'],
steps=[['Kies één concreet patroon, zoals automatisch instemmen of een idee blijven uitstellen.','Onderzoek wanneer dat patroon helpt en wanneer het beperkt.','Ontwerp een kleine opdracht die een andere keuze uitnodigt.','Reflecteer zonder een juiste uitkomst af te dwingen en kies een volgende stap.'],['Choose a specific pattern, such as automatically agreeing or repeatedly postponing an idea.','Explore when the pattern helps and when it limits you.','Design a small activity that invites a different choice.','Reflect without forcing a correct outcome, then choose a next step.']],
case=['Changetrek & Ondernemen met Ballen','Changetrek & Ondernemen met Ballen'],
casebody=['Voor Changetrek werkte ik aan een persoonlijke ontwikkelingsreis met storytelling en reflectie. Met Ondernemen met Ballen ontwikkelde ik als medeoprichter workshops en actiegerichte ervaringen rond lef en ondernemerschap. Dit werk verbindt persoonlijke vragen met iets wat je zelf kunt onderzoeken.','For Changetrek, I contributed to a personal development journey using storytelling and reflection. As co-founder of Ondernemen met Ballen, I developed workshops and action-focused experiences around courage and entrepreneurship. This work connects personal questions to something participants can explore for themselves.'],
fit=['Voor programmamakers, opleiders en organisaties die een ervaring voor persoonlijke ontwikkeling willen laten ontwerpen of begeleiden. Mijn aanbod begint bij een gezamenlijke ontwerpvraag voor een groep of programma; er staat geen vast individueel coachingstraject op deze site.','For programme designers, educators and organisations commissioning a personal development experience. My offer begins with a shared design challenge for a group or programme; this site does not offer a fixed individual coaching programme.'],
prompt=['Welk patroon willen jullie deelnemers laten onderzoeken?','Which pattern would you like participants to explore?'])
]
for page in pages:
    for lang in ['nl','en']:
        i=lang=='en'; home='index-en.html' if i else 'index.html'; media='media-en.html' if i else 'media.html'
        title=page['title'][i]; cta='Let’s explore your challenge ↗' if i else 'Laten we je vraag verkennen ↗'
        subtitle='A practical starting point' if i else 'Een praktisch begin'
        approach='Four starting questions' if i else 'Vier stappen om te beginnen'
        portfolio='An example from my work' if i else 'Een voorbeeld uit mijn werk'
        fit='Who is this for?' if i else 'Voor wie is dit?'
        subject='Your challenge: '+title if i else 'Jouw vraag: '+title
        from urllib.parse import quote
        mail='mailto:chantalke@gmail.com?subject='+quote(subject)
        links=''.join(f'<li><a href="{p[lang]}.html">{escape(p["title"][i])}</a></li>' for p in pages if p is not page)
        html=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Chantal van Kempen</title><meta name="description" content="{escape(page['intro'][i],quote=True)}"><link rel="alternate" hreflang="nl" href="{page['nl']}.html"><link rel="alternate" hreflang="en" href="{page['en']}.html"><link rel="stylesheet" href="style.css?v=gold-2"></head><body><header><a class="brand" href="{home}">Chantal<br>van Kempen<span class="brand-symbol">{cosmic_mark}</span></a><nav aria-label="{'Main navigation' if i else 'Hoofdnavigatie'}"><a href="{home}#routes">{'Your challenge' if i else 'Jouw vraag'}</a><a href="{home}#werk">{'The work' if i else 'Het werk'}</a><a href="{media}">Media</a><a class="nav-contact" href="https://www.linkedin.com/in/chantalvankempen/" target="_blank" rel="noopener noreferrer">Say hi ↗</a><span class="language-switch"><a href="{page['nl']}.html" lang="nl" {'aria-current="true"' if not i else ''}>NL</a><span>/</span><a href="{page['en']}.html" lang="en" {'aria-current="true"' if i else ''}>EN</a></span></nav></header><main><article class="section article"><p class="eyebrow">{subtitle.upper()} / CHANTAL VAN KEMPEN</p><h1>{escape(title)}</h1><p class="large">{escape(page['intro'][i])}</p><h2>{escape(page['heading'][i])}</h2><p>{escape(page['body'][i])}</p><h2>{approach}</h2><ol>{''.join('<li>'+escape(s)+'</li>' for s in page['steps'][i])}</ol><div class="case-callout"><p class="eyebrow">{portfolio.upper()}</p><h3>{escape(page['case'][i])}</h3><p>{escape(page['casebody'][i])}</p><a href="{home}#werk">{'Explore my projects' if i else 'Bekijk mijn projecten'} ↗</a></div><h2>{fit}</h2><p>{escape(page['fit'][i])}</p><h2>{escape(page['prompt'][i])}</h2><p>{'Tell me about your situation. We’ll explore whether an experiential approach fits and what preparation and follow-up would be useful.' if i else 'Vertel me over jullie situatie. Samen onderzoeken we of een ervaringsgerichte aanpak past en welke voorbereiding en opvolging nodig zijn.'}</p><a class="button yellow" href="{mail}">{cta}</a><h2>{'Related challenges' if i else 'Andere vraagstukken'}</h2><ul>{links}</ul></article></main><footer><span>Chantal van Kempen · Experience designer</span><a href="{home}">{'Back to my world' if i else 'Terug naar mijn wereld'} ↗</a></footer></body></html>'''
        (root/(page[lang]+'.html')).write_text(html)
